INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-9', 'iPhone 17 Pro Max', 'Apple', 37999, 39520, 'iphones', 'nuevo', 'Nuevo', NULL, 'Destaca principalmente por incorporar una estructura unibody de aluminio forjado en caliente, un sistema de enfriamiento por cámara de vapor y una pantalla de 6.9 pulgadas protegida por la tecnología Ceramic Shield 2', ARRAY['Cable de carga tipo C','Garantía']::text[], ARRAY['Nuevo y sellado']::text[], '{"colors":[{"hex":"#EBEBEB","hsl":"0, 0%, 92%","rgb":"235, 235, 235","name":"Silver","oklch":"0.940, 0.000, 89.9","value":"#EBEBEB"},{"hex":"#0042AA","hsl":"217, 100%, 33%","rgb":"0, 66, 170","name":"Azul","oklch":"0.417, 0.177, 260.7","value":"#0042AA"}],"storage":[{"name":"256GB","price":37999,"stock":3,"old_price":39520}]}'::jsonb, ARRAY['https://content.macstore.mx/img/sku/IPHONE783_FZ.jpg','https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/catalog/public/products/product_IPHONE_17PROMAX_256GB_SILVER_694f75dc8c32d.webp']::text[], 'https://content.macstore.mx/img/sku/IPHONE783_FZ.jpg', '2026-08-11T23:24:38.226+00:00', '2026-08-20T21:37:22.272+00:00');
