INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-11', 'iPhone 15', 'Apple', 12700, 13250, 'iphones', 'seminuevo', 'Seminuevo', 89, 'El iPhone 15 es un teléfono de gama alta desarrollado por Apple, caracterizado principalmente por la integración del puerto USB-C, la inclusión de la Dynamic Island (Isla Dinámica) en los modelos base y un sensor de cámara principal mejorado de 48 megapíxeles.', ARRAY['Cable Lightning','Garantía']::text[], ARRAY['Bateria en 89%','eSIM']::text[], '{"colors":[{"hex":"#F9D3E0","hsl":"339, 76%, 90%","rgb":"249, 211, 224","name":"Rosado","oklch":"0.903, 0.046, 355.5","value":"#F9D3E0"}],"storage":[{"name":"128GB","price":12700,"stock":1,"old_price":13250}]}'::jsonb, ARRAY['https://www.phonelectrics.com/cdn/shop/files/iPhone15-2.jpg?v=1738330167&width=820']::text[], 'https://www.phonelectrics.com/cdn/shop/files/iPhone15-2.jpg?v=1738330167&width=820', '2026-08-11T23:34:45.885+00:00', '2026-08-27T17:10:00.223+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-12', 'iPhone 15 Plus', 'Apple', 14600, 15200, 'iphones', 'seminuevo', 'Seminuevo', 100, 'El iPhone 15 Plus es un teléfono inteligente diseñado por Apple que destaca por su pantalla OLED de 6.7 pulgadas, su batería de larga duración con hasta 26 horas de reproducción de video, y la inclusión de la isla dinámica (Dynamic Island) junto con el puerto USB-C.', ARRAY['Cable tipo C','Garantía']::text[], ARRAY['Batería en 100%','eSIM']::text[], '{"colors":[{"hex":"#CAF0FE","hsl":"196, 96%, 89%","rgb":"202, 240, 254","name":"Celeste","oklch":"0.932, 0.044, 222.1","value":"#CAF0FE"}],"storage":[{"name":"128GB","price":14600,"stock":1,"old_price":15200}]}'::jsonb, ARRAY['https://www.kasigra.it/1375-medium_default/apple-iphone-15-128gb-azzurro-garanzia-europa-24-mesi.jpg']::text[], 'https://www.kasigra.it/1375-medium_default/apple-iphone-15-128gb-azzurro-garanzia-europa-24-mesi.jpg', '2026-08-11T23:52:17.494+00:00', '2026-08-27T17:09:33.94+00:00');
