INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-15', 'iPhone 16 Pro', 'Apple', 21200, 22050, 'iphones', 'seminuevo', 'Seminuevo', 100, 'El iPhone 16 Pro destaca por su pantalla de 6.3 pulgadas, el potente chip A18 Pro enfocado en inteligencia artificial y la incorporación del nuevo botón físico Camera Control.', ARRAY['Cable USB-C','Garantia']::text[], ARRAY['Batería en 100%','eSIM']::text[], '{"colors":[{"hex":"#FFECD5","hsl":"33, 100%, 92%","rgb":"255, 236, 213","name":"Dorado","oklch":"0.952, 0.037, 72.6","value":"#FFECD5"},{"hex":"#FFFFFF","hsl":"0, 0%, 100%","rgb":"255, 255, 255","name":"Blanco","oklch":"1.000, 0.000, 89.9","value":"#FFFFFF"}],"storage":[{"name":"128GB","price":21200,"stock":1,"old_price":22050},{"name":"256GB","price":22500,"stock":1,"old_price":23400}]}'::jsonb, ARRAY['https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/catalog/public/products/product_IPHONE_16PRO_256GB_NATURAL_6870d6b2f3039.webp','https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/catalog/public/products/product_IPHONE_16PROMAX_256GB_WHITE_6870d6c69ab6e.webp']::text[], 'https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/catalog/public/products/product_IPHONE_16PRO_256GB_NATURAL_6870d6b2f3039.webp', '2026-08-12T00:12:08.805+00:00', '2026-08-27T17:11:29.857+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-16', 'iPhone 12', 'Apple', 8200, 8530, 'iphones', 'seminuevo', 'Seminuevo', 100, 'El iPhone 12 es un teléfono inteligente desarrollado por Apple que destaca por incorporar conectividad 5G, una pantalla OLED Super Retina XDR y el chip A14 Bionic. Introdujo un diseño renovado con bordes planos de aluminio que recuerda a modelos clásicos y cuenta con la protección Ceramic Shield en su pantalla para mayor resistencia contra caídas.', ARRAY['Cable Lightning','Garantía']::text[], ARRAY['Batería en 100%']::text[], '{"colors":[{"hex":"#B18CFE","hsl":"259, 98%, 77%","rgb":"177, 140, 254","name":"Morado","oklch":"0.722, 0.164, 297.1","value":"#B18CFE"},{"hex":"#0061FF","hsl":"217, 100%, 50%","rgb":"0, 97, 255","name":"Azul","oklch":"0.554, 0.246, 261.4","value":"#0061FF"},{"hex":"#E0EDD4","hsl":"91, 41%, 88%","rgb":"224, 237, 212","name":"Verde","oklch":"0.930, 0.036, 129.7","value":"#E0EDD4"}],"storage":[{"name":"128GB","price":8200,"stock":3,"old_price":8530}]}'::jsonb, ARRAY['https://www.apple.com/newsroom/images/product/iphone/geo/apple_iphone-12_2-up_geo_10132020_inline.jpg.large.jpg','https://m.media-amazon.com/images/I/51rqWfzdqyL._AC_UF894,1000_QL80_.jpg','https://i5.walmartimages.ca/asr/c2e54432-d97a-485a-bfc8-0d06adb22317.9abcdd3bf10ae4663d39bde2d25d59c5.jpeg']::text[], 'https://www.apple.com/newsroom/images/product/iphone/geo/apple_iphone-12_2-up_geo_10132020_inline.jpg.large.jpg', '2026-08-15T21:05:43.844+00:00', '2026-08-27T15:22:28.844+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-17', 'iPHone 17 (Nuevo)', 'Apple', 26500, 27560, 'iphones', 'nuevo', 'Nuevo', NULL, 'La familia iPhone 17 de Apple se compone de cuatro modelos principales orientados a diferentes tipos de usuario. Los dispositivos introducen pantallas más fluidas y un rediseño en sus lentes frontales y materiales', ARRAY['Cable USB-C','Garantía']::text[], '{}', '{"colors":[{"hex":"#D9CAFE","hsl":"257, 96%, 89%","rgb":"217, 202, 254","name":"Lavander","oklch":"0.868, 0.073, 298.1","value":"#D9CAFE"},{"hex":"#FFFFFF","hsl":"0, 0%, 100%","rgb":"255, 255, 255","name":"Blanco","oklch":"1.000, 0.000, 89.9","value":"#FFFFFF"}],"storage":[{"name":"256GB","price":26500,"stock":2,"old_price":27560}]}'::jsonb, ARRAY['https://www.apple.com/newsroom/images/2025/09/apple-debuts-iphone-17/article/Apple-iPhone-17-hero-250909_inline.jpg.large.jpg','https://media.binglee.com.au/cdn-cgi/image/fit=scale-down,f=auto,w=1079/a/5/4/6/a546af4fe0687021e3bbe5204fba36d3f91ea26b_Apple_MG6K4XA_Iphone_Hero_1.jpg']::text[], 'https://www.apple.com/newsroom/images/2025/09/apple-debuts-iphone-17/article/Apple-iPhone-17-hero-250909_inline.jpg.large.jpg', '2026-08-15T21:32:19.549+00:00', '2026-08-20T21:04:03.301+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-18', 'Samsung S23 Ultra', 'Samsung', 13800, 14350, 'samsung', 'seminuevo', 'Seminuevo', NULL, 'El Samsung Galaxy S23 Ultra sigue siendo uno de los teléfonos de gama alta más potentes y equilibrados del mercado. Equipado con el procesador Snapdragon 8 Gen 2 for Galaxy, una espectacular pantalla de 6.8 pulgadas Quad HD+ y un avanzado sistema de cámara de 200 MP, este dispositivo ofrece un re', ARRAY['Cable USB-C','Garantía']::text[], '{}', '{"colors":[{"hex":"#CAF0FE","hsl":"196, 96%, 89%","rgb":"202, 240, 254","name":"Celeste","oklch":"0.932, 0.044, 222.1","value":"#CAF0FE"}],"storage":[{"name":"256GB","price":13800,"stock":null,"old_price":14350}]}'::jsonb, ARRAY['https://cdn1.smartprix.com/rx-i3mlY205k-w420-h420/samsung-galaxy-s23-u.webp']::text[], 'https://cdn1.smartprix.com/rx-i3mlY205k-w420-h420/samsung-galaxy-s23-u.webp', '2026-08-15T21:45:21.43+00:00', '2026-08-15T21:45:21.43+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-19', 'Samsung A36', 'Samsung', 7000, 7280, 'samsung', 'nuevo', 'Nuevo', NULL, 'El Samsung Galaxy A36 5G es un teléfono de gama media lanzado en marzo de 2025 que destaca por equilibrar un rendimiento fluido, funciones básicas de Inteligencia Artificial ("Awesome Intelligence") y una de las mejores políticas de soporte en su categoría', ARRAY['Cable de carga','Garanría']::text[], '{}', '{"colors":[{"hex":"#D9CAFE","hsl":"257, 96%, 89%","rgb":"217, 202, 254","name":"Lavander","oklch":"0.868, 0.073, 298.1","value":"#D9CAFE"}],"storage":[{"name":"128GB","price":7000,"stock":1,"old_price":7280}]}'::jsonb, ARRAY['https://m.media-amazon.com/images/I/51kxnf0PyrL._AC_UF894,1000_QL80_.jpg']::text[], 'https://m.media-amazon.com/images/I/51kxnf0PyrL._AC_UF894,1000_QL80_.jpg', '2026-08-16T00:05:45.583+00:00', '2026-08-16T00:05:45.583+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-20', 'Samsung A07', 'Samsung', 3500, 3640, 'samsung', 'nuevo', 'Nuevo', NULL, 'El Samsung Galaxy A07 es el teléfono de gama de entrada más económico de la marca.', ARRAY['Cable de carga','Garantía']::text[], '{}', '{"colors":[{"hex":"#232323","hsl":"0, 0%, 14%","rgb":"35, 35, 35","name":"Negro","oklch":"0.256, 0.000, 89.9","value":"#232323"},{"hex":"#D9CAFE","hsl":"257, 96%, 89%","rgb":"217, 202, 254","name":"Morado","oklch":"0.868, 0.073, 298.1","value":"#D9CAFE"}],"storage":[{"name":"128GB","price":3500,"stock":4,"old_price":3640}]}'::jsonb, ARRAY['https://yas.co.tz/wp-content/uploads/2026/05/a07.png','https://dcdn-us.mitiendanube.com/stores/003/280/428/products/d_nq_np_2x_902363-mla92380662685_092025-f-35e46e1249c7aeb29317580374950869-1024-1024.webp']::text[], 'https://yas.co.tz/wp-content/uploads/2026/05/a07.png', '2026-08-16T00:10:55.049+00:00', '2026-08-16T00:10:55.049+00:00');
