INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-22', 'Samsung Galaxy S21 Ultra', 'Samsung', 8300, 8640, 'samsung', 'seminuevo', 'Seminuevo', NULL, 'Destaca por ofrecer características insignia (como su pantalla Quad HD+ a 120Hz y un zoom óptico de 10x) a un precio de mercado secundario muy competitivo, posicionándose como una gran alternativa de presupuesto frente a las gamas medias actuales.', ARRAY['Cable USB-C','Garantía']::text[], '{}', '{"colors":[{"hex":"#232323","hsl":"0, 0%, 14%","rgb":"35, 35, 35","name":"Negro","oklch":"0.256, 0.000, 89.9","value":"#232323"}],"storage":[{"name":"128GB","price":8300,"stock":1,"old_price":8640}]}'::jsonb, ARRAY['https://tecexpresshn.com/wp-content/uploads/2024/02/s21-ultra-1-e1712683784955.webp']::text[], 'https://tecexpresshn.com/wp-content/uploads/2024/02/s21-ultra-1-e1712683784955.webp', '2026-08-20T21:46:17.265+00:00', '2026-08-20T21:46:17.265+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-23', 'Apple Pencil Type C', 'Apple', 3500, 3640, 'accessories', 'nuevo', 'Nuevo', NULL, 'El Apple Pencil (USB-C) es el modelo más accesible de la línea de lápices ópticos de Apple, diseñado principalmente para estudiantes, tareas escolares y productividad general. Destaca por incluir un puerto físico USB-C oculto bajo una tapa deslizante para su emparejamiento y carga mediante cable.', '{}', '{}', '{"colors":[{"hex":"#CCCCCC","hsl":"0, 0%, 80%","rgb":"204, 204, 204","name":"Estándar","oklch":"0.845, 0.000, 89.9","value":"#CCCCCC"}],"storage":[{"name":"ESTANDAR","price":3500,"stock":1,"old_price":3640}]}'::jsonb, ARRAY['https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/cache/catalog/public/products/product_MUWA3AM_A_6870d7138ec87-500x500.webp','https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/MUWA3?wid=1000&hei=1000&fmt=jpeg&qlt=95&.v=1695933856697']::text[], 'https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/cache/catalog/public/products/product_MUWA3AM_A_6870d7138ec87-500x500.webp', '2026-08-20T21:50:12.042+00:00', '2026-08-20T21:51:02.264+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-24', 'EarPods Type C', 'Apple', 980, 980, 'accessories', 'nuevo', 'Nuevo', NULL, 'Los Apple EarPods (USB-C) son audífonos cableados oficiales de Apple diseñados para ofrecer un sonido de alta calidad directamente a través de un puerto tipo C, ideales para modelos recientes de iPhone, iPad y computadoras Mac.', '{}', '{}', '{"colors":[{"hex":"#CCCCCC","hsl":"0, 0%, 80%","rgb":"204, 204, 204","name":"Estándar","oklch":"0.845, 0.000, 89.9","value":"#CCCCCC"}],"storage":[{"name":"ESTANDAR","price":980,"stock":null,"old_price":980}]}'::jsonb, ARRAY['https://geeky.sfo2.cdn.digitaloceanspaces.com/geekydrop_production/d_nq_np_697061-mla75572388718_042024-o.webp-839zYy57s.webp','https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/catalog/public/products/product_MTJY3AM_A_6870e89de2f24.webp']::text[], 'https://geeky.sfo2.cdn.digitaloceanspaces.com/geekydrop_production/d_nq_np_697061-mla75572388718_042024-o.webp-839zYy57s.webp', '2026-08-20T21:58:47.591+00:00', '2026-08-20T21:58:47.591+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-25', 'EarPods Type Lightning', 'Apple', 980, 980, 'accessories', 'nuevo', 'Nuevo', NULL, 'Los Apple EarPods con conector Lightning son los audífonos alámbricos oficiales de Apple diseñados específicamente para dispositivos que no cuentan con entrada de audio tradicional de 3.5 mm, conectándose directamente al puerto de carga', '{}', '{}', '{"colors":[{"hex":"#CCCCCC","hsl":"0, 0%, 80%","rgb":"204, 204, 204","name":"Estándar","oklch":"0.845, 0.000, 89.9","value":"#CCCCCC"}],"storage":[{"name":"ESTANDAR","price":980,"stock":null,"old_price":980}]}'::jsonb, ARRAY['https://siman.vtexassets.com/arquivos/ids/6290875-800-auto?v=638653882194970000&width=800&height=auto&aspect=true','https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/MMTN2?wid=2000&hei=2000&fmt=jpeg&qlt=95&.v=Z01ZWSs0MExIUHN1S2VNREx3amRoV2orYzFkTG5HaE9wejd5WUxYZjRML3VlaGtpaWc2M1pZRjFsclpzd3lPRFRHL0QxcnpjcmRVR29kRCt2bHZPb3c']::text[], 'https://siman.vtexassets.com/arquivos/ids/6290875-800-auto?v=638653882194970000&width=800&height=auto&aspect=true', '2026-08-20T22:02:24.483+00:00', '2026-08-20T22:02:24.483+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-26', 'Apple Watch SE 3th GEN/ 44mm', 'Apple', 9500, 9880, 'accessories', 'nuevo', 'Nuevo', NULL, 'El Apple Watch SE 3 en color Starlight (Blanco Estelar) es el reloj inteligente de entrada de Apple. Este dispositivo destaca por mantener un precio accesible de $249 USD e introducir mejoras drásticas respecto a su antecesor, como la pantalla siempre activa y el potente chip S10', ARRAY['Garantía']::text[], ARRAY['Nuevo']::text[], '{"colors":[{"hex":"#D6D6D6","hsl":"0, 0%, 84%","rgb":"214, 214, 214","name":"Starlight","oklch":"0.876, 0.000, 89.9","value":"#D6D6D6"}],"storage":[{"name":"ESTANDAR","price":9500,"stock":1,"old_price":9880}]}'::jsonb, ARRAY['https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/MYJ33ref_VW_34FR+watch-case-40-aluminum-starlight-nc-se3_VW_34FR+watch-face-40-aluminum-starlight-se3_VW_34FR?wid=752&hei=720&bgc=fafafa&trim=1&fmt=p-jpg&qlt=80&.','https://www.apple.com/v/apple-watch-se-3/b/images/overview/on-the-go/go_ping__gb8mux6dn8y2_large.jpg']::text[], 'https://store.storeimages.cdn-apple.com/1/as-images.apple.com/is/MYJ33ref_VW_34FR+watch-case-40-aluminum-starlight-nc-se3_VW_34FR+watch-face-40-aluminum-starlight-se3_VW_34FR?wid=752&hei=720&bgc=fafafa&trim=1&fmt=p-jpg&qlt=80&.', '2026-08-20T22:11:09.467+00:00', '2026-08-20T22:11:09.467+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-27', 'Apple Watch Series 11/ 42mm', 'Apple', 13400, 13940, 'accessories', 'nuevo', 'Nuevo', NULL, 'El Apple Watch Series 11 en color Oro Rosa (Rose Gold) destaca como una de las opciones más sofisticadas de la línea de aluminio de Apple, presentando un acabado mate cepillado muy elegante. Apple empareja por defecto este estuche con la correa deportiva en tono Light Blush (Rubor Claro), eliminando por completo el antiguo color blanco estelar (Starlight) de esta generación.', ARRAY['Garantía']::text[], ARRAY['Nuevo']::text[], '{"colors":[{"hex":"#F9D3E0","hsl":"339, 76%, 90%","rgb":"249, 211, 224","name":"Rose Gold","oklch":"0.903, 0.046, 355.5","value":"#F9D3E0"}],"storage":[{"name":"ESTANDAR","price":13400,"stock":1,"old_price":13940}]}'::jsonb, ARRAY['https://i5.walmartimages.com/seo/Apple-Watch-Series-11-GPS-Cellular-42mm-Rose-Gold-Aluminum-Case-with-Light-Blush-Sport-Band-S-M_0f49bd52-4921-4a79-8f2f-de608912a693.c4a5fb77937c6d9679bbda387cbfa13f.jpeg','https://www.apple.com/v/apple-watch-series-11/c/images/overview/highlights/highlights_glass_endframe__f39nueq3bfiy_large.jpg']::text[], 'https://i5.walmartimages.com/seo/Apple-Watch-Series-11-GPS-Cellular-42mm-Rose-Gold-Aluminum-Case-with-Light-Blush-Sport-Band-S-M_0f49bd52-4921-4a79-8f2f-de608912a693.c4a5fb77937c6d9679bbda387cbfa13f.jpeg', '2026-08-20T22:14:54.382+00:00', '2026-08-20T22:14:54.382+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-28', 'iPhone 13 Pro Max', 'Apple', 15400, 16020, 'iphones', 'seminuevo', 'Seminuevo', 100, 'El iPhone 13 Pro Max destaca por ser uno de los dispositivos premium más equilibrados de Apple, famoso por consolidar una de las mejores autonomías de batería en la historia de la marca y por introducir la pantalla ProMotion.', ARRAY['Cable de carga','Garantía']::text[], ARRAY['100% de batería']::text[], '{"colors":[{"hex":"#EBEBEB","hsl":"0, 0%, 92%","rgb":"235, 235, 235","name":"Blanco","oklch":"0.940, 0.000, 89.9","value":"#EBEBEB"},{"hex":"#CAF0FE","hsl":"196, 96%, 89%","rgb":"202, 240, 254","name":"Celeste","oklch":"0.932, 0.044, 222.1","value":"#CAF0FE"}],"storage":[{"name":"512GB","price":15400,"stock":4,"old_price":16020},{"name":"1TB","price":15500,"stock":1,"old_price":16120}]}'::jsonb, ARRAY['https://www.apple.com/newsroom/images/product/iphone/geo/Apple_iPhone-13-Pro_iPhone-13-Pro-Max_GEO_09142021_inline.jpg.large.jpg','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRRH-7_lJkYuwW7H2RIF-4LUdQa4JrPBd7dSG-drdtffEvAFpAVzkciRs6f&s=10']::text[], 'https://www.apple.com/newsroom/images/product/iphone/geo/Apple_iPhone-13-Pro_iPhone-13-Pro-Max_GEO_09142021_inline.jpg.large.jpg', '2026-08-27T15:46:57.859+00:00', '2026-08-27T15:49:17.196+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-29', 'iPhone 14 Pro', 'Apple', 13800, 14352, 'iphones', 'seminuevo', 'Seminuevo', 100, 'Destaca por introducir la Dynamic Island (Isla Dinámica), una pantalla siempre activa y un potente sensor de cámara principal de 48 megapíxeles.', ARRAY['Cable de carga','Garantía']::text[], ARRAY['Batería en 100%','eSIM']::text[], '{"colors":[{"hex":"#450E59","hsl":"284, 73%, 20%","rgb":"69, 14, 89","name":"Morado","oklch":"0.301, 0.129, 314.9","value":"#450E59"},{"hex":"#EBEBEB","hsl":"0, 0%, 92%","rgb":"235, 235, 235","name":"Blanco","oklch":"0.940, 0.000, 89.9","value":"#EBEBEB"}],"storage":[{"name":"128GB","price":13800,"stock":2,"old_price":14352},{"name":"256GB","price":14800,"stock":2,"old_price":15392}]}'::jsonb, ARRAY['https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/catalog/public/products/product_IPHONE_14PRO_256GB_PURPLE_ESIM_68710bb1cfcd7.webp','https://www.apple.com/newsroom/images/product/iphone/geo/Apple-iPhone-14-Pro-iPhone-14-Pro-Max-silver-220907-geo_inline.jpg.large.jpg']::text[], 'https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/catalog/public/products/product_IPHONE_14PRO_256GB_PURPLE_ESIM_68710bb1cfcd7.webp', '2026-08-27T15:55:24.92+00:00', '2026-08-27T17:10:50.058+00:00');
INSERT INTO productos (id,title,brand,price,old_price,category,condition,badge,battery_health,description,includes,specs,variants,images,image,created_at,updated_at) VALUES ('producto-30', 'iPhone 16', 'Apple', 17600, 19344, 'iphones', 'seminuevo', 'Seminuevo', 100, 'Esta generación destaca principalmente por la inclusión del potente chip A18, la integración nativa de Apple Intelligence, y la incorporación del nuevo botón físico Control de Cámara.', ARRAY['Cable de carga','Garantía']::text[], ARRAY['Batería en 100%','eSIM']::text[], '{"colors":[{"hex":"#ED719E","hsl":"338, 78%, 69%","rgb":"237, 113, 158","name":"Rosado","oklch":"0.707, 0.159, 359.1","value":"#ED719E"}],"storage":[{"name":"128GB","price":17600,"stock":3,"old_price":19344}]}'::jsonb, ARRAY['https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/catalog/public/products/product_IPHONE_16_128GB_PINK_6870d53b40864.webp','https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/cache/catalog/public/products/product_IPHONE_16_128GB_PINK_6870d53ccc931-500x500.webp']::text[], 'https://jetstereo-retail.s3.us-east-2.amazonaws.com/images/catalog/public/products/product_IPHONE_16_128GB_PINK_6870d53b40864.webp', '2026-08-27T16:41:43.457+00:00', '2026-08-27T17:11:17.405+00:00');
